{
  "mode": "compile",
  "question": null,
  "asks_about": "tolerance",
  "unresolved": [],
  "understanding": "The job involves re-rolling stainless steel foil from parent coils into retail rolls, ensuring the grade (321 or 309) matches the order and that the foil is completely free of oil or grease. Technicians wear cut gloves for safety and document the process by photographing the parent coil's mill tag and the final labeled box to prevent shipping the wrong grade.",
  "draft": {
    "key": "foil-rerolling-and-packaging",
    "title": "Stainless Steel Foil Re-rolling and Packaging",
    "strictness": 2,
    "minimum_tier": "open",
    "disqualifiers": [
      "Parent coil mill tag does not match the customer order grade."
    ],
    "releases": [
      "Retail roll is approved for shipment to Amazon customers."
    ],
    "steps": [
      {
        "title": "Verify Parent Coil Grade",
        "explanation": "321 and 309 foils look identical but have different temperature ratings. Mixing them up will ruin a customer's tool steel during heat treatment.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "parent_mill_tag_photo",
            "kind": "photo",
            "prompt": "Take a photo of the parent coil's mill tag showing the grade (321 or 309) next to the roll.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "acceptance_description": "The mill tag must be clearly readable and the grade must match the customer order.",
            "guidance": "Ensure the grade printed on the mill tag is in sharp focus and matches the order sheet."
          }
        ]
      },
      {
        "title": "Safety and Setup",
        "explanation": "Foil edges are razor-sharp and will cause severe cuts if handled with bare hands.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "cut_gloves_worn",
            "kind": "choice",
            "prompt": "Are you wearing cut-resistant gloves for handling the foil?",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "Yes, cut gloves are worn",
              "No"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "Yes, cut gloves are worn",
            "guidance": "Cut gloves must be worn for absolutely any step that involves touching the foil."
          }
        ]
      },
      {
        "title": "Re-roll and Inspect Foil",
        "explanation": "Any oil or grease on the foil will bake into the customer's workpiece during heat treatment, ruining it.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "oil_grease_check",
            "kind": "choice",
            "prompt": "Did you detect any oil, grease, or residue on the foil during the run?",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "No oil or grease detected",
              "Oil or grease detected (scrap section)"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "No oil or grease detected",
            "guidance": "Keep your eyes on the foil and feel it as it winds. If you see or feel any grease, that section must be scrapped immediately."
          }
        ]
      },
      {
        "title": "Box and Label Verification",
        "explanation": "We must prove that the grade on the retail box matches the parent coil we actually rolled.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "finished_box_photo",
            "kind": "photo",
            "prompt": "Take a photo of the finished box showing the readable grade label before taping it up.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "acceptance_description": "The retail box label must be clearly readable and match the grade verified on the parent coil mill tag.",
            "guidance": "Position the box so the label is fully visible and legible in the photo."
          }
        ]
      },
      {
        "title": "Sign-off",
        "explanation": "The technician packing the order takes responsibility for the grade match and cleanliness of the roll.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "technician_signature",
            "kind": "signature",
            "prompt": "Sign to confirm the roll was inspected, boxed, and matches the order.",
            "source": "human",
            "required_at_strictness": 2,
            "acceptance_rule": "signed_by",
            "guidance": "Your signature confirms that the grade on the box matches the parent coil and no grease was present."
          }
        ]
      }
    ]
  }
}
